CREATE TABLE public.food_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, name text NOT NULL, quantity text NOT NULL DEFAULT '1', location text NOT NULL DEFAULT 'Fridge', category text NOT NULL DEFAULT 'Produce', purchase_date date NOT NULL DEFAULT CURRENT_DATE, expiry_date date NOT NULL, date_type text NOT NULL DEFAULT 'best before', opened_date date, recommended_date date, notes text NOT NULL DEFAULT '', emoji text NOT NULL DEFAULT '🥬', status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.food_items TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.food_items TO authenticated; GRANT ALL ON public.food_items TO service_role; ALTER TABLE public.food_items ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read samples or own food" ON public.food_items FOR SELECT USING (user_id IS NULL OR auth.uid() = user_id); CREATE POLICY "Insert own food" ON public.food_items FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Update own food" ON public.food_items FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE POLICY "Delete own food" ON public.food_items FOR DELETE TO authenticated USING (auth.uid() = user_id); CREATE TABLE public.food_preferences (user_id uuid PRIMARY KEY, dietary text NOT NULL DEFAULT 'No preference', allergies text NOT NULL DEFAULT '', dislikes text NOT NULL DEFAULT '', cooking_time integer NOT NULL DEFAULT 30, servings integer NOT NULL DEFAULT 2, reminder_days integer[] NOT NULL DEFAULT '{7,3,1}'); GRANT SELECT, INSERT, UPDATE, DELETE ON public.food_preferences TO authenticated; GRANT ALL ON public.food_preferences TO service_role; ALTER TABLE public.food_preferences ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own preferences" ON public.food_preferences FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); INSERT INTO public.food_items (name,quantity,location,category,expiry_date,date_type,opened_date,recommended_date,emoji) VALUES ('Baby spinach','200 g','Fridge','Produce',CURRENT_DATE+1,'use by',NULL,NULL,'🥬'),('Greek yogurt','500 g','Fridge','Dairy',CURRENT_DATE+5,'use by',CURRENT_DATE-1,CURRENT_DATE+1,'🥛'),('Avocados','2 pieces','Cupboard','Produce',CURRENT_DATE+2,'best before',NULL,NULL,'🥑'),('Cherry tomatoes','250 g','Fridge','Produce',CURRENT_DATE+3,'best before',NULL,NULL,'🍅'),('Whole milk','1 litre','Fridge','Dairy',CURRENT_DATE-1,'use by',NULL,NULL,'🥛'),('Chicken breast','400 g','Freezer','Raw meat',CURRENT_DATE+60,'best before',NULL,NULL,'🍗'),('Carrots','500 g','Fridge','Produce',CURRENT_DATE+8,'best before',NULL,NULL,'🥕'),('Eggs','6 pieces','Fridge','Eggs',CURRENT_DATE+12,'best before',NULL,NULL,'🥚'),('Pasta','500 g','Pantry','Dry goods',CURRENT_DATE+120,'best before',NULL,NULL,'🍝'),('Chickpeas','1 tin','Cupboard','Canned food',CURRENT_DATE+180,'best before',NULL,NULL,'🥫'),('Cheddar cheese','200 g','Fridge','Dairy',CURRENT_DATE+14,'best before',CURRENT_DATE-1,CURRENT_DATE+2,'🧀'),('Frozen peas','500 g','Freezer','Produce',CURRENT_DATE+90,'best before',NULL,NULL,'🫛');